function validate([heights]) {
  if (!Array.isArray(heights) || heights.length < 1 || heights.length > 100000) return 'heights needs 1 to 100000 values.';
  if (heights.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each height is an integer from 1 to 10^9.';
  return null;
}

