function findBuildings(heights) {
  const result = [];
  for (let i = 0; i < heights.length; i++) {
    let open = true;
    for (let j = i + 1; j < heights.length; j++) {
      if (heights[j] >= heights[i]) open = false;
    }
    if (open) result.push(i);
  }
  return result;
}

