function generate(rand, size) {
  if (size === 'large') {
    const n = 1500 + Math.floor(rand() * 501);
    const mode = rand();
    if (mode < 0.4) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 1000000000))];
    // A mostly falling skyline keeps many buildings visible.
    let level = 1000000000;
    return [Array.from({ length: n }, () => {
      level = Math.max(1, level - Math.floor(rand() * 600000));
      return rand() < 0.1 ? 1 + Math.floor(rand() * 1000000000) : level;
    })];
  }
  const n = 1 + Math.floor(rand() * 10);
  const top = rand() < 0.7 ? 5 : 1000000000;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
